// tests/golden/*.json (generated by `uv run python -m pipeline.make_golden`, never hand-edited):
// the TS harmonize/analytics/time code must reproduce the Python reference.
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { harmonize, monthPercentile, type KUsed } from './harmonize';
import { assess, criticalPeriod, monthToDate, quantile, summarize, trend, type Assessment, type CriticalPeriod, type Trend } from './analytics';
import { dekadIndex, dekadMonth, dekadRange, dekadYear } from './time';
import type { AoiSeries, Calibration, Manifest } from '../data/types';

const GOLDEN = resolve(import.meta.dirname, '../../../tests/golden');
const load = (f: string) => JSON.parse(readFileSync(resolve(GOLDEN, f), 'utf8'));
const timeCases = load('time_cases.json');
const hCases = load('harmonize_cases.json');
const aCases = load('analytics_cases.json');

type Num = number | null | undefined;
/** null in golden = NaN/undefined; TS may give NaN or null. */
function close(actual: Num, expected: Num, rel: number, abs: number, what: string) {
  if (expected === null || expected === undefined) {
    expect(actual === null || actual === undefined || Number.isNaN(actual), `${what}: expected null, got ${actual}`).toBe(true);
    return;
  }
  expect(typeof actual === 'number' && Number.isFinite(actual), `${what}: expected ${expected}, got ${actual}`).toBe(true);
  const tol = abs + rel * Math.abs(expected);
  expect(Math.abs((actual as number) - expected) <= tol, `${what}: ${actual} vs ${expected}`).toBe(true);
}

describe('golden: time', () => {
  it('dekad_index', () => {
    for (const c of timeCases.dekad_index) expect(dekadIndex(c.date), c.date).toBe(c.t);
  });
  it('dekad_range', () => {
    for (const c of timeCases.dekad_range) {
      expect(dekadRange(c.t)).toEqual(c.range);
      expect(dekadMonth(c.t)).toBe(c.month);
      expect(dekadYear(c.t)).toBe(c.year);
    }
  });
});

describe('golden: harmonize', () => {
  const { rel, abs } = hCases.tolerance;
  for (const c of hCases.cases) {
    it(c.name, () => {
      const inp = c.input;
      const series: AoiSeries = {
        level: 1, t0: inp.t0, nT: inp.nT, tiles: inp.tiles, perTile: inp.perTile.map((a: number[]) => Float64Array.from(a)),
        nCells: 0, fetched: [], ms: 0,
      };
      const h = harmonize(series, inp.manifest as Manifest, inp.calibration as Calibration | null);
      const e = c.expected;
      expect(h.years).toEqual(e.years);
      expect(h.tSwitch).toBe(e.tSwitch);
      expect(h.tN20).toBe(e.tN20);
      const checkK = (got: KUsed[], exp: { k: Num; lo: Num; hi: Num; stratum: string }[], tag: string) =>
        exp.forEach((x, m) => {
          expect(got[m].stratum, `${tag}[${m}].stratum`).toBe(x.stratum);
          for (const f of ['k', 'lo', 'hi'] as const) close(got[m][f], x[f], rel, abs, `${tag}[${m}].${f}`);
        });
      checkK(h.kModis, e.kModis, 'kModis');
      checkK(h.kN20, e.kN20, 'kN20');
      expect(h.rows.length).toBe(e.rows.length);
      e.rows.forEach((x: Record<string, Num | string | boolean> | null, i: number) => {
        const r = h.rows[i];
        if (x === null) {
          expect(r, `row ${i}`).toBeNull();
          return;
        }
        expect(r, `row ${i}`).not.toBeNull();
        const tag = `${x.year}-${x.month}`;
        expect([r!.year, r!.month, r!.era, r!.partial, r!.nDekads], tag).toEqual([x.year, x.month, x.era, x.partial, x.nDekads]);
        expect(r!.kUsed?.stratum ?? null, `${tag}.stratum`).toBe(x.stratum);
        for (const f of ['modis', 'snpp', 'n20', 'viirs', 'spliced', 'harmonized', 'lo', 'hi'] as const)
          close(r![f], x[f] as Num, rel, abs, `${tag}.${f}`);
      });
      for (const p of e.percentile) close(monthPercentile(h, p.month, p.value, p.excludeYear), p.expected, rel, abs, `percentile m${p.month}`);
      // the dekadal series (S4 addition) sums to the monthly rows
      for (const r of h.rows) {
        if (!r) continue;
        let s = 0;
        for (let i = 0; i < h.dekadal.length; i++) {
          const t = h.t0 + i;
          if (dekadYear(t) === r.year && dekadMonth(t) === r.month) s += h.dekadal[i];
        }
        if (Number.isFinite(r.harmonized)) close(s, r.harmonized, rel, abs, `dekadal ${r.year}-${r.month}`);
        else expect(Number.isNaN(s)).toBe(true);
      }
    });
  }
});

describe('golden: analytics', () => {
  const { rel, abs, trend_p_abs: pAbs } = aCases.tolerance;
  const checkAssess = (got: Assessment, exp: Assessment, tag: string) => {
    close(got.percentile, exp.percentile, rel, abs, `${tag}.percentile`);
    expect(got.label, `${tag}.label`).toBe(exp.label);
    close(got.z, exp.z, rel, abs, `${tag}.z`);
    for (const f of ['median', 'p10', 'p25', 'p75', 'p90'] as const) close(got.clim[f], exp.clim[f], rel, abs, `${tag}.clim.${f}`);
    expect(got.clim.n).toBe(exp.clim.n);
  };
  const checkCrit = (got: CriticalPeriod | null, exp: { start_month: number; length: number; months: number[]; share: number } | null, tag: string) => {
    if (exp === null) return expect(got, tag).toBeNull();
    expect(got, tag).not.toBeNull();
    expect([got!.startMonth, got!.length, got!.months], tag).toEqual([exp.start_month, exp.length, exp.months]);
    close(got!.share, exp.share, rel, abs, `${tag}.share`);
  };
  const checkTrend = (got: Trend | null, exp: Trend | null, tag: string) => {
    if (exp === null) return expect(got, tag).toBeNull();
    expect(got, tag).not.toBeNull();
    for (const f of ['slopePerYear', 'pctPerYear', 'medianAnnual', 'varS', 'z'] as const) close(got![f], exp[f], rel, abs, `${tag}.${f}`);
    expect([got!.s, got!.n], tag).toEqual([exp.s, exp.n]);
    close(got!.p, exp.p, 0, pAbs, `${tag}.p`);
  };

  it('rules text is present (spec lives in pipeline/analytics.py)', () => {
    expect(aCases.rules).toContain('critical period');
  });
  it('quantile', () => {
    for (const c of aCases.quantile) close(quantile(c.xs, c.q), c.expected, rel, abs, `q(${c.xs}, ${c.q})`);
  });
  it('assess: percentile, label, z, climatology', () => {
    aCases.assess.forEach((c: { value: number; base: number[]; expected: Assessment }, i: number) =>
      checkAssess(assess(c.value, c.base), c.expected, `assess[${i}]`),
    );
  });
  it('monthToDate', () => {
    aCases.monthToDate.forEach((c: { current: number[]; base: number[][]; expected: Assessment & { dekads: number; value: number; ratio: Num } }, i: number) => {
      const got = monthToDate(c.current, c.base);
      expect(got.dekads).toBe(c.expected.dekads);
      close(got.value, c.expected.value, rel, abs, `mtd[${i}].value`);
      close(got.ratio, c.expected.ratio, rel, abs, `mtd[${i}].ratio`);
      checkAssess(got, c.expected, `mtd[${i}]`);
    });
  });
  it('criticalPeriod', () => {
    aCases.criticalPeriod.forEach((c: { medians: number[]; expected: Parameters<typeof checkCrit>[1] }, i: number) =>
      checkCrit(criticalPeriod(c.medians), c.expected, `crit[${i}]`),
    );
  });
  it('trend: Theil–Sen + Mann–Kendall', () => {
    aCases.trend.forEach((c: { years: number[]; annual: number[]; expected: Trend | null }, i: number) =>
      checkTrend(trend(c.years, c.annual), c.expected, `trend[${i}]`),
    );
  });

  for (const fs of aCases.fromSeries) {
    it(`fromSeries: ${fs.case}`, () => {
      const hc = hCases.cases.find((c: { name: string }) => c.name === fs.case);
      const inp = hc.input;
      const h = harmonize(
        { level: 1, t0: inp.t0, nT: inp.nT, tiles: inp.tiles, perTile: inp.perTile.map((a: number[]) => Float64Array.from(a)), nCells: 0, fetched: [], ms: 0 },
        inp.manifest,
        inp.calibration,
      );
      const s = summarize(h, fs.currentYear);
      const e = fs.expected;
      expect(s.baselineYears).toEqual(fs.baselineYears);
      e.climatology.forEach((c: Assessment['clim'], m: number) => {
        for (const f of ['median', 'p10', 'p25', 'p75', 'p90'] as const) close(s.climatology[m][f], c[f], rel, abs, `clim[${m}].${f}`);
        expect(s.climatology[m].n).toBe(c.n);
      });
      expect(s.currentMonths.map((x) => x.month)).toEqual(e.currentMonths.map((x: { month: number }) => x.month));
      e.currentMonths.forEach((x: Assessment & { month: number; value: number }, i: number) => {
        close(s.currentMonths[i].value, x.value, rel, abs, `cur[${x.month}].value`);
        checkAssess(s.currentMonths[i], x, `cur[${x.month}]`);
      });
      checkCrit(s.criticalPeriod, e.criticalPeriod, 'criticalPeriod');
      expect(s.annual.length).toBe(e.annual.length);
      e.annual.forEach((a: number, i: number) => close(s.annual[i], a, rel, abs, `annual[${i}]`));
      checkTrend(s.trend, e.trend, 'trend');
    });
  }
});
